body.query:
UPDATE system.appearance [_id == '00000000-0000-7000-8000-00000000000a'] {
  linkPatterns: $linkPatterns
}

SELECT system.ai_providers { slug, displayName, providerType := config.providerType }
FILTER isActive == true
SORT +sortOrder

INSERT system.ai_providers {
  slug: $slug,
  displayName: $displayName,
  credentialEnv: $credentialEnv,
  config: $config,
  isActive: $isActive,
  sortOrder: $sortOrder
} -> { _id, slug }

SELECT system.email_providers { slug, displayName, providerType := config.providerType }
FILTER isActive == true
SORT +sortOrder

SELECT system.email_settings {
  defaultProvider := (SELECT defaultProvider { _id, slug })
}
FILTER _id == '00000000-0000-7000-8000-000000000010'
TAKE 1

UPDATE system.email_settings [_id == '00000000-0000-7000-8000-000000000010'] {
  defaultProvider: $providerId
}

SELECT system.email_templates { messageId, subject, body }
FILTER messageId == $messageId
TAKE 1

UPDATE system.email_templates [messageId == $messageId] {
  subject: $subject,
  body: $body
}

UPDATE system.alert_queries [_id == $alertId AND state == $expectedOldState AND isActive == true] {
    state: 'firing',
    lastFiredAt: now()
  } -> { _id, ownerId }

UPDATE system.alert_queries [_id == $alertId AND state == 'unknown'] {
    state: 'ok'
  } -> { _id }

UPDATE system.alert_queries [_id == $alertId AND state == 'firing' AND isActive == true] {
    state: 'ok',
    lastResolvedAt: now()
  } -> { _id, ownerId }

INSERT system.alert_queries {
    ownerId: $ownerId,
    name: $name,
    description: $description,
    query: $query,
    trackingEntries: $trackingEntries,
    state: $state,
    notifyOnResolve: $notifyOnResolve
  } -> { _id }

INSERT system.alert_notifications {
    alertId: $alertId,
    ownerId: $ownerId,
    type: $type,
    occurredAt: now(),
    payload: $payload
  } -> { _id }

UPDATE system.alert_queries [_id == $alertId] {
    trackingStale: true
  } -> { _id }

SELECT system.alert_queries {
    _id,
    trackingEntries
  }

UPDATE system.alert_queries [_id == $alertId] {
    lastError: $error,
    errorCount: errorCount + 1
  } -> { _id, errorCount }

UPDATE system.alert_queries [_id == $alertId] {
    lastEvaluatedAt: now(),
    errorCount: 0,
    lastError: NULL
  } -> { _id }

UPDATE system.alert_notifications [_id == $notificationId AND ownerId == $context.userId] {
    readAt: now()
  } -> { _id }

UPDATE system.alert_notifications [ownerId == $context.userId AND readAt == NULL] {
    readAt: now()
  }

UPDATE system.alert_notifications [_id == $notificationId AND ownerId == $context.userId] {
    dismissedAt: now()
  } -> { _id }

UPDATE system.alert_queries [_id == $alertId] {
    query: $query,
    trackingEntries: $trackingEntries,
    trackingStale: false,
    state: 'unknown',
    lastEvaluatedAt: now(),
    lastError: NULL,
    errorCount: 0
  } -> { _id }

UPDATE system.alert_queries [_id == $alertId] {
    isActive: $isActive,
    lastError: $lastError,
    stoppedBy: $stoppedBy
  } -> { _id }

UPDATE system.alert_queries [_id == $alertId AND ownerId == $ownerId] {
    name: $name,
    description: $description,
    notifyOnResolve: $notifyOnResolve
  } -> { _id }

SELECT system.alert_queries {
    code := 'ALERT_OWNER_MISSING_READ',
    missingKeys := ARRAY[]::text[]
  } FILTER _id == $alertId(type: string, required) AND ownerId == $context.userId AND false

SELECT system.cache_entries { key, value, cacheScope, expiresAt }
  FILTER user == $context.userId AND key == $key AND expiresAt > now()
  TAKE 1

LOCK 'cache-write', $context.userId;
  DELETE system.cache_entries [user == $context.userId AND expiresAt < now()];
  INSERT system.cache_entries {
    user: $context.userId,
    key: $key(type: string, required),
    cacheScope: 'user',
    value: $value(type: object, required),
    expiresAt: now() + make_interval(0, 0, 0, 0, 0, 0, coalesce($ttlSeconds(type: integer)::numeric, $env.CACHE_TTL_DEFAULT_SECONDS::numeric))
  } ON CONFLICT (user, key) DO UPDATE {
    value: $value,
    expiresAt: now() + make_interval(0, 0, 0, 0, 0, 0, coalesce($ttlSeconds::numeric, $env.CACHE_TTL_DEFAULT_SECONDS::numeric))
  };
  $evicted := SELECT system.cache_entries { _id }
    FILTER user == $context.userId AND expiresAt >= now()
    SORT -(key == $key), -_createdAt, -_id
    TAKE $env.CACHE_PER_USER_QUOTA..;
  DELETE system.cache_entries [_id IN $evicted._id];

$interaction := SELECT system.interactions
    { _id, schema, status, inAudience := can(answerKey, params) ?? false }
    FILTER _id == $interactionId;
  ASSERT $interaction._id != NULL
    status: 404, code: 'InteractionNotFoundError', message: 'Interaction not found';
  ASSERT $interaction.inAudience
    status: 403, code: 'ForbiddenError', message: 'This request is not addressed to you';
  ASSERT $interaction.status != 'closed'
    status: 409, code: 'InteractionClosedError', message: 'This request is closed: the run that raised it is no longer running.';
  ASSERT $interaction.status == 'pending'
    status: 409, code: 'InteractionAlreadyAnsweredError', message: 'Interaction is already completed';
  $check := system.checkSchema(schema: $interaction.schema, value: $response);
  ASSERT $check.valid
    status: 400, code: 'BadRequestError', message: 'The response does not match the request''s form';
  UPDATE system.interactions
    [ _id == $interactionId AND status == 'pending' ]
    { status: 'pending' };
  $held := SELECT system.interactions
    { _id, status, closeWhen, audienceSize, inAudience := can(answerKey, params) ?? false }
    FILTER _id == $interactionId;
  ASSERT $held._id != NULL
    status: 404, code: 'InteractionNotFoundError', message: 'Interaction not found';
  ASSERT $held.inAudience
    status: 403, code: 'ForbiddenError', message: 'This request is not addressed to you';
  ASSERT $held.status != 'closed'
    status: 409, code: 'InteractionClosedError', message: 'This request is closed: the run that raised it is no longer running.';
  ASSERT $held.status == 'pending'
    status: 409, code: 'InteractionAlreadyAnsweredError', message: 'Interaction is already completed';
  $mine := SELECT system.interaction_answers { _id } FILTER interaction == $interactionId AND respondedBy == $context.userId;
  ASSERT $mine._id == NULL
    status: 409, code: 'InteractionAlreadyAnsweredError', message: 'You have already answered this request';
  INSERT system.interaction_answers {
    interaction: $interactionId,
    respondedBy: $context.userId,
    respondedAt: clock_timestamp(),
    response: $check.value
  };
  $tally := SELECT system.interactions
    { answers := (SELECT system.interaction_answers { userId := respondedBy._id, respondedAt, response } FILTER interaction == $interactionId SORT respondedAt, _id) }
    FILTER _id == $interactionId;
  $closes := system.evaluateRule(
    expression: $held.closeWhen,
    input: jsonb_build_object('answers', $tally.answers, 'audienceSize', $held.audienceSize));
  UPDATE system.interactions [_id == $interactionId AND $closes == true] {
    response: $check.value,
    respondedAt: clock_timestamp(),
    status: 'completed',
    respondedBy: $context.userId
  };
  DELETE system.interaction_param_sources [interaction == $interactionId AND $closes == true];
  SELECT { response := $check.value }

UPDATE system.user_notifications [recipient == $context.userId AND readAt == NULL AND kind == 'mention'] {
    readAt: now()
  }

UPDATE system.user_notifications [_id == $notificationId AND recipient == $context.userId AND kind == 'mention'] {
    readAt: now()
  } -> { _id }

UPDATE system.user_notifications [recipient == $context.userId AND readAt == NULL AND kind == 'assignment'] {
    readAt: now()
  }

UPDATE system.user_notifications [_id == $notificationId AND recipient == $context.userId AND kind == 'assignment'] {
    readAt: now()
  } -> { _id }

UPDATE system.user_notifications [_id == $notificationId AND recipient == $context.userId] {
    dismissedAt: now()
  } -> { _id }

INSERT system.app_notifications {
    recipient: $recipient,
    title: $title,
    body: $body,
    targetTableId: $targetTableId,
    targetRowId: $targetRowId,
    targetTablePath: $targetTablePath
  } -> { _id }

UPDATE system.app_notifications [recipient == $context.userId AND readAt == NULL] {
    readAt: now()
  }

UPDATE system.app_notifications [_id == $notificationId AND recipient == $context.userId] {
    readAt: now()
  } -> { _id }

UPDATE system.app_notifications [_id == $notificationId AND recipient == $context.userId] {
    dismissedAt: now()
  } -> { _id }

INSERT system.inbox_last_looks {
    user: $context.userId,
    source: $source(type: text, required),
    lookedAt: now()
  } ON CONFLICT (user, source) DO UPDATE {
    lookedAt: now()
  }

select system.models {
    _id,
    type,
    isSystem,
    path := (parent.parent + '.' + parent + '.' + name ?? parent + '.' + name),
    metadata }

SELECT system.models { _id, name, physicalName, isSystem, metadata, type, parentId := parent._id }
  FILTER parent == $tableId AND type == 'constraint'
  SORT +name

SELECT system.model_artifacts { declarationId, ruleKey, constraintType, judge, enforcement, pgName, applied, reason, reads }
  FILTER tableId == $tableId and type == 'constraint'
  SORT +ruleKey, +declarationId

SELECT system.settings { value }
  FILTER key == 'auth.selfRegistration'
  TAKE 1

UPDATE system.settings [key == 'auth.selfRegistration'] {
    value: $value
  } -> { key, value }

SELECT system.settings { value }
  FILTER key == 'auth.anonymousAccess'
  TAKE 1

UPSERT system.settings [key == 'auth.anonymousAccess'] {
    key: 'auth.anonymousAccess',
    value: jsonb_build_object('enabled', $enabled(type: boolean))
  } -> { key, value }

SELECT system.settings { value }
  FILTER key == 'auth.clientRegistration'
  TAKE 1

UPSERT system.settings [key == 'auth.clientRegistration'] {
    key: 'auth.clientRegistration',
    value: jsonb_build_object('enabled', $enabled(type: boolean))
  } -> { key, value }

SELECT system.settings { value }
  FILTER key == 'auth.clientMetadataDocuments'
  TAKE 1

UPSERT system.settings [key == 'auth.clientMetadataDocuments'] {
    key: 'auth.clientMetadataDocuments',
    value: jsonb_build_object('enabled', $enabled(type: boolean))
  } -> { key, value }

SELECT system.settings { value }
  FILTER key == 'auth.assuranceWindows'
  TAKE 1

UPSERT system.settings [key == 'auth.assuranceWindows'] {
    key: 'auth.assuranceWindows',
    value: jsonb_build_object(
      'aal1', $aal1(type: integer),
      'aal2', $aal2(type: integer),
      'aal3', $aal3(type: integer)
    )
  } -> { key, value }

SELECT system.settings { baseLanguage := jsonb_extract_path_text(value, 'tag') }
  FILTER key == 'i18n.baseLanguage'
  TAKE 1

UPSERT system.settings [key == 'i18n.baseLanguage'] {
    key: 'i18n.baseLanguage',
    value: jsonb_build_object('tag', $tag(type: text))
  } -> { key, value }

SELECT system.settings { value }
  FILTER key == 'auth.userDeactivation'
  TAKE 1

UPSERT system.settings [key == 'auth.userDeactivation'] {
    key: 'auth.userDeactivation',
    value: jsonb_build_object('enabled', $enabled(type: boolean))
  } -> { key, value }

INSERT system.env {
    key: $key(type: string, required),
    description: $description,
    isSecret: $isSecret(type: boolean, required),
    value: $value
  } -> { _id, key }

UPDATE system.env [key == $key(type: string, required)] {
    value: $value
  } -> { _id, key }

UPDATE system.env [key == $key(type: string, required)] {
    value: null
  } -> { _id, key }

UPDATE system.env [key == $key(type: string, required)] {
    description: $description
  } -> { _id, key }

SUMMARIZE system.outbox_event {
    queued := count(*),
    runnable := count(*) IF (
      (blockerJob == NULL OR blockerJob.status == 'completed' OR blockerJob.status == 'failed')
      AND (blockerInteraction == NULL OR blockerInteraction.status != 'pending')
      AND waitUntil <= now()
    ),
    oldest := min(occurredAt) IF (
      (blockerJob == NULL OR blockerJob.status == 'completed' OR blockerJob.status == 'failed')
      AND (blockerInteraction == NULL OR blockerInteraction.status != 'pending')
      AND waitUntil <= now()
    )
  } FILTER currentNodeId != NULL

UPDATE system.webhook_deliveries [_id == $_id(type: string, required)] {
    run: $run(type: string, required)
  } -> { _id }

SUMMARIZE system.job_queue {
    queued := count(*),
    runnable := count(*) IF (nextAttemptAt == NULL OR nextAttemptAt <= now()),
    oldest := min(_createdAt) IF (nextAttemptAt == NULL OR nextAttemptAt <= now())
  } FILTER status == 'pending'

SELECT system.knowledgebase {
    _id, title, slug, icon, parent := parent._id, ordinal, content, _updatedAt, _updatedBy,
    _comments := (SELECT EXPAND _comments { _id, _versionId, anchor, author, authorId := author._id, body, _createdAt, parent, resolvedAt, resolvedBy, resolvedById := resolvedBy._id } SORT _createdAt)
  } FILTER slug == $slug

INSERT system.migration_plans {
    planId: $planId(type: string, required),
    user: $userId(type: string, required),
    payload: $payload(type: object, required),
    expiresAt: now() + make_interval(0, 0, 0, 0, 0, 0, $ttlSeconds(type: integer, required)::numeric)
  } -> { _id }

SELECT system.migration_plans { payload, decisions }
  FILTER planId == $planId(type: string, required) AND consumedAt IS NULL AND expiresAt > now()
  TAKE 1

UPDATE system.migration_plans
    [planId == $planId(type: string, required) AND consumedAt IS NULL AND expiresAt > now()]
    { decisions: jsonb_set(decisions, $path(type: text[], required), $answer(type: jsonb, required)) }
    -> { _id }

UPDATE system.migration_plans
    [planId == $planId(type: string, required) AND consumedAt IS NULL AND expiresAt > now()]
    { consumedAt: now() }
    -> { payload, decisions }

UPDATE system.migration_plans
    [planId == $planId(type: string, required) AND consumedAt IS NOT NULL AND expiresAt > now()]
    { consumedAt: null }
    -> { _id }

INSERT system.rate_limit_windows {
    key: $key(type: text, required),
    hits: 1,
    windowEndsAt: now() + make_interval(0, 0, 0, 0, 0, 0, $windowMs(type: integer, required)::numeric / 1000)
  } ON CONFLICT (key) DO UPDATE {
    hits: CASE(windowEndsAt <= now(), 1, hits + 1),
    windowEndsAt: CASE(windowEndsAt <= now(), now() + make_interval(0, 0, 0, 0, 0, 0, $windowMs::numeric / 1000), windowEndsAt)
  } -> { hits, windowEndsAt }

SELECT system.rate_limit_windows { hits, windowEndsAt }
  FILTER key == $key(type: text, required) AND windowEndsAt > now()
  TAKE 1

SELECT auth.users {
    _id,
    username,
    emails
}
FILTER (username == $identifier(type: string, required) AND username NOT LIKE '%@%')
    OR emails HAS (lower(email) == lower($identifier) AND verified != null AND email LIKE '%@%');

SELECT auth.emails {
    _id,
    email,
    verified,
    primary,
    userInfo := @row (SELECT user { _id, username })
}
FILTER primary == true AND lower(email) == lower($email(type: string, required));

SELECT auth.emails {
    _id,
    email,
    verified,
    primary,
    userInfo := @row (SELECT user { _id })
}
FILTER lower(email) == lower($email(type: string, required)) AND (verified IS NOT NULL OR primary == true);

SELECT auth.emails {
    _id,
    userId := user._id
}
FILTER lower(email) == lower($email(type: string, required)) AND (verified IS NULL AND (primary IS NULL OR primary == false)) AND user != $userId(type: string, required);

SELECT auth.decision_matrix { key }
  FILTER enabled == true
    AND role.users HAS (_id == $userId)

BEGIN;
  REQUIRED UPDATE auth.addresses [_id == $addressId AND user == $context.userId] { primary: true };
  UPDATE auth.addresses [user == $context.userId AND primary == true AND _id != $addressId] { primary: false };
  COMMIT;

UPDATE auth.tokens [
    _id == $_id(type: string, required)
    AND (type == 'application' OR type == 'service')
    AND (
      lastUsedAt == $seenLastUsedAt
      OR ($seenLastUsedAt == NULL AND lastUsedAt == NULL)
    )
  ] {
    lastUsedAt: $now(type: string, required)
  } -> { _id }

ASSERT CASE(regexp_like($clientId(type: string, required)::text, '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'), $clientId::uuid != '00000000-0000-7000-a000-000000000003'::uuid, true)
    status: 403, code: 'ForbiddenError', message: 'The default client cannot be a service client';
  REQUIRED SELECT auth.clients { _id } FILTER _id == CASE(regexp_like($clientId::text, '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'), $clientId::uuid, NULL);
  REQUIRED SELECT auth.tokens { _id }
  FILTER _id == CASE(regexp_like($tokenId(type: string, required)::text, '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'), $tokenId::uuid, NULL) AND type == 'service' AND client == $clientId;
  $token := SELECT auth.tokens {
    live := revokedAt == NULL AND (expires == NULL OR expires > now())
  } FILTER _id == $tokenId::uuid TAKE 1;
  ASSERT $token.live
    status: 403, code: 'ForbiddenError', message: 'That token has already ended. Reload the client to see its tokens.';
  UPDATE auth.tokens [_id == $tokenId::uuid AND type == 'service' AND revokedAt == NULL] {
    revokedAt: now()
  } -> { _id, revokedAt }

UPDATE auth.tokens [
    _id == $_id(type: string, required)
    AND (type == 'application' OR type == 'service')
    AND revokedAt == NULL
  ] {
    revokedAt: $now(type: string, required)
  } -> { _id }

UPDATE auth.tokens [
    _id == $tokenId(type: string, required)
    AND type == 'application'
    AND user == $context.userId
    AND revokedAt == NULL
  ] {
    revokedAt: now()
  } -> { _id }

SUMMARIZE auth.tokens {
    count := count(*)
  } FILTER type == 'application'
    AND user == $userId(type: string, required)
    AND revokedAt == NULL
    AND (expires == NULL OR expires > $now(type: string, required))

UPDATE auth.tokens [
    _id == $_id(type: string, required)
    AND (type == 'application' OR type == 'service')
    AND (expires == NULL OR expires > $expires(type: string, required))
  ] {
    expires: $expires
  } -> { _id }

UPDATE auth.tokens [
    _id == $_id(type: string, required)
    AND type == 'application'
    AND aal < $aal(type: integer, required)
  ] {
    aal: $aal
  } -> { _id }

UPDATE auth.tokens [
    _id == $_id(type: string, required)
    AND type == 'application'
  ] {
    scopes: $scopes
  } -> { _id }

SELECT auth.auth_attempts {
      _id,
      success,
      _createdAt
  }
  FILTER identifier == $identifier AND _createdAt > $since
  SORT -_id
  TAKE 500;

INSERT auth.auth_attempts {
    user: $userId,
    identifier: $identifier,
    kind: $kind,
    success: $success,
    ip: $ip
  } -> { _id }

INSERT auth.auth_audit_logs {
    actor: $actorUserId,
    targetUser: $targetUserId,
    action: $action(type: string, required),
    ip: $ip,
    detail: $detail(type: object, required)
  } -> { _id }

SELECT auth.clients {
      _id,
      @decrypt apiKey
  }
  FILTER (_id::text == $lookup OR shortName == $lookup OR clientIdMetadataUrl == $lookup) AND isActive == true;

SELECT auth.clients {
    _id, name, shortName, description, isActive, isIdp, logoUri, verified, _createdAt,
    mySessions := (SELECT EXPAND tokens { _id, revokedAt, device, browser, os, isCurrent := _id == $context.sessionId } FILTER type == 'session' AND user == $context.userId AND revokedAt == NULL)
  }
  FILTER tokens HAS (type == 'session' AND user == $context.userId AND revokedAt == NULL)

UPDATE auth.clients [_id == $clientId(type: string, required)] {
    publisher: $publisher,
    softwareId: $softwareId,
    softwareVersion: $softwareVersion,
    verified: $verified(type: boolean, required)
  } -> { * }

UPDATE auth.clients [_id::text == $clientId(type: string, required) AND clientIdMetadataUrl != NULL] {
    clientUri: $clientUri,
    contacts: $contacts,
    logoUri: $logoUri,
    metadataExpiresAt: $metadataExpiresAt,
    name: $name,
    redirectUrls ?= $redirectUrls,
    redirectUrlsFromDocument ?= $redirectUrlsFromDocument
  } -> { _id }

INSERT auth.device_authorizations {
    deviceCodeHash: $deviceCodeHash(type: string, required),
    userCode: $userCode(type: string, required),
    client: $client(type: string, required),
    scope: $scope(type: string, required),
    expiresAt: $expiresAt(type: string, required),
    interval: $interval(type: number, required),
    status: 'pending'
  } -> { _id }

UPDATE auth.device_authorizations [
    userCode == $userCode(type: string, required)
    AND status == 'pending'
    AND expiresAt > $now(type: string, required)
  ] {
    status: $status(type: string, required),
    userId: $userId,
    grantedScope: $grantedScope,
    acr: $acr,
    amr: $amr,
    proofTimes: $proofTimes
  } -> { _id }

SELECT auth.device_authorizations { *, clientId := client._id }
  FILTER deviceCodeHash == $deviceCodeHash(type: string, required)
  TAKE 1

UPDATE auth.device_authorizations [
    _id == $_id(type: string, required)
    AND (
      lastPolledAt == $seenLastPolledAt
      OR ($seenLastPolledAt == NULL AND lastPolledAt == NULL)
    )
  ] {
    lastPolledAt: $now(type: string, required),
    interval: $interval(type: number, required)
  } -> { _id }

DELETE auth.device_authorizations [
    _id == $_id(type: string, required)
    AND status == $status(type: string, required)
  ] -> { _id }

SELECT auth.emails {
      _id,
      email,
      label,
      verified,
      primary
  }
  FILTER user == $context.userId
  SORT +_createdAt, +_id;

$target := SELECT auth.emails { _id, verified } FILTER _id == $emailId AND user == $context.userId;
  ASSERT $target._id != NULL
    status: 404, code: 'NotFoundError', message: 'Email not found';
  ASSERT $target.verified != NULL
    status: 400, code: 'BadRequestError', message: 'To make it primary, the email must be verified';
  UPDATE auth.emails [user == $context.userId AND primary == true AND _id != $emailId] { primary: false };
  REQUIRED UPDATE auth.emails [_id == $emailId AND user == $context.userId] { primary: true };

$target := SELECT auth.emails { _id } FILTER _id == $emailId AND user == $userId;
  ASSERT $target._id != NULL
    status: 404, code: 'NotFoundError', message: 'Email not found';
  UPDATE auth.emails [user == $userId AND primary == true AND _id != $emailId] { primary: false };
  REQUIRED UPDATE auth.emails [_id == $emailId AND user == $userId] { primary: true };

$held := SELECT auth.emails { _id } FILTER user == $context.userId AND lower(email) == lower($email) TAKE 1;
  ASSERT $held._id == NULL
    status: 400, code: 'EmailAlreadyOnAccountError', message: 'This email address is already on your account.';
  $added := INSERT auth.emails { email: $email, label: $label, primary: false, user: $context.userId } -> { _id, email, label, primary, verified };
  $owner := SELECT auth.users { username } FILTER _id == $context.userId;
  $queued := job.sendEmail(
    message: 'account.email_confirm',
    to: $added.email,
    variables: jsonb_build_object('accountUsername', $owner.username),
    links: jsonb_build_object('confirmUrl', jsonb_build_object('path', '/confirm-email', 'params', jsonb_build_object('identifier', $added.email),
      'token', jsonb_build_object('purpose', 'email_verify', 'userId', $context.userId, 'emailId', $added._id, 'param', 'token')))
  );
  SELECT auth.emails { _id, email, label, primary, verified } FILTER user == $context.userId AND lower(email) == lower($email);

$target := SELECT auth.emails { _id, email } FILTER _id == $emailId AND user == $context.userId;
  ASSERT $target._id != NULL
    status: 404, code: 'NotFoundError', message: 'Email not found';
  $owner := SELECT auth.users { username } FILTER _id == $context.userId;
  $r := job.sendEmail(
    message: 'account.email_confirm',
    to: $target.email,
    variables: jsonb_build_object('accountUsername', $owner.username),
    links: jsonb_build_object('confirmUrl', jsonb_build_object('path', '/confirm-email', 'params', jsonb_build_object('identifier', $target.email),
      'token', jsonb_build_object('purpose', 'email_verify', 'userId', $context.userId, 'emailId', $target._id, 'param', 'token')))
  );
  ASSERT ($r.reason ?? '') != 'rate-limited'
    status: 429, code: 'TooManyRequestsError', message: 'Too many messages were queued for this account just now, so the verification message was not sent. Try again in a minute.';
  ASSERT $r.queued
    status: 503, code: 'ServiceUnavailableError', message: 'This base cannot send email right now, so the verification message was not sent.';
  SELECT { queued := $r.queued };

$target := SELECT auth.emails { _id, email, wasPrimary := primary } FILTER _id == $emailId AND user == $context.userId;
  ASSERT $target._id != NULL
    status: 404, code: 'NotFoundError', message: 'Email not found';
  $others := SELECT auth.emails { _id } FILTER user == $context.userId AND _id != $emailId TAKE 1;
  ASSERT $others._id != NULL
    status: 400, code: 'BadRequestError', message: 'Cannot delete the last email address';
  $successor := SELECT auth.emails { _id, email } FILTER user == $context.userId AND _id != $emailId AND verified != NULL SORT +_createdAt, +_id TAKE 1;
  ASSERT $target.wasPrimary != true OR $successor._id != NULL
    status: 400, code: 'BadRequestError', message: 'Cannot remove the primary email address: verify another address first';
  $kept := SELECT auth.emails { _id, email } FILTER user == $context.userId AND primary == true AND _id != $emailId;
  UPDATE auth.emails [_id == $emailId AND user == $context.userId AND primary == true] { primary: false };
  UPDATE auth.emails [_id == $successor._id AND user == $context.userId AND $kept._id == NULL] { primary: true };
  $queued := job.sendEmail(
    message: 'account.email_removed',
    to: $kept.email ?? $successor.email ?? $target.email,
    variables: jsonb_build_object('removedEmail', $target.email),
    links: jsonb_build_object('emailsUrl', jsonb_build_object('path', '/account/emails'))
  );
  // After the notice: a named result is read where it is used, so the removed row
  // is gone from `$target` once the delete has run.
  DELETE auth.emails [_id == $emailId AND user == $context.userId];
  SELECT { _id := $emailId };

