  DELETE EFFECTIVE FROM ($end(type: date, default: null) ?? current_date) auth.team_memberships [_id == $membershipId];
  COMMIT;

$held := SELECT EFFECTIVE ALL auth.team_memberships { _id } FILTER team == $fromTeamId AND user == $userId AND _effectiveFrom <= ($moveOn(type: date, default: null) ?? current_date) AND (_effectiveTo == NULL OR _effectiveTo > ($moveOn(type: date, default: null) ?? current_date)) TAKE 1;
  ASSERT $held._id != NULL
    status: 404, code: 'NotFoundError', message: 'The person has no membership in the team they are moved from';
  UPDATE EFFECTIVE ALL auth.team_memberships [team == $fromTeamId AND user == $userId AND _effectiveFrom <= ($moveOn(type: date, default: null) ?? current_date) AND (_effectiveTo == NULL OR _effectiveTo > ($moveOn(type: date, default: null) ?? current_date))] { reason: $reason };
  DELETE EFFECTIVE FROM ($moveOn(type: date, default: null) ?? current_date) auth.team_memberships [team == $fromTeamId AND user == $userId];
  INSERT EFFECTIVE FROM ($moveOn(type: date, default: null) ?? current_date) auth.team_memberships { team: $toTeamId, user: $userId, kind: $kind, reason: $reason };
  $left := SELECT EFFECTIVE ALL auth.team_memberships { _id } FILTER team == $fromTeamId AND user == $userId AND _effectiveFrom <= ($moveOn(type: date, default: null) ?? current_date) AND (_effectiveTo == NULL OR _effectiveTo > ($moveOn(type: date, default: null) ?? current_date)) TAKE 1;
  ASSERT $left._id == NULL
    status: 403, code: 'ForbiddenError', message: 'The membership could not be ended: the caller may not change it';
  $arrived := SELECT EFFECTIVE ALL auth.team_memberships { _id } FILTER team == $toTeamId AND user == $userId AND _effectiveFrom <= ($moveOn(type: date, default: null) ?? current_date) AND (_effectiveTo == NULL OR _effectiveTo > ($moveOn(type: date, default: null) ?? current_date)) TAKE 1;
  ASSERT $arrived._id != NULL
    status: 403, code: 'ForbiddenError', message: 'The person could not be added to the team they are moved to';

