SELECT storage.local_bucket_credentials {
      _id,
      accessKey,
      @decrypt secretKey,
      permissions,
      isRoot,
      expiresAt,
      bucketId := bucketId._id,
      bucket := bucketId.name
  } FILTER isActive == true

ASSERT coalesce(length($name(type: string)::text), 0) >= 1 AND coalesce(length($name::text), 0) <= 255
    status: 400, code: 'BadRequestError', message: 'name must be 1 to 255 characters';
  ASSERT $expiresAt(type: string)::text == NULL OR regexp_like($expiresAt::text, '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]+)?)?(Z|[+-][0-9]{2}:?[0-9]{2})$')
    status: 400, code: 'BadRequestError', message: 'expiresAt must be ISO 8601 with an explicit UTC offset or Z';
  ASSERT coalesce($permissions(type: text[]), ARRAY[]::text[]) <@ ARRAY['ListBuckets', 'CreateBucket', 'DeleteBucket', 'HeadBucket', 'GetBucketLocation', 'GetBucketVersioning', 'PutBucketVersioning', 'PutObject', 'GetObject', 'HeadObject', 'DeleteObject', 'ListObjects', 'ListObjectsV2', 'ListObjectVersions', 'CreateMultipartUpload', 'UploadPart', 'CompleteMultipartUpload', 'AbortMultipartUpload', 'ListParts', 'ListMultipartUploads', 'PutObjectTagging', 'GetObjectTagging', 'DeleteObjectTagging']::text[]
    status: 400, code: 'BadRequestError', message: 'permissions must be operations a credential can be granted';
  $bucket := SELECT storage.buckets { _id } FILTER _id::text == $bucketId(type: string) TAKE 1;
  ASSERT $bucketId == NULL OR $bucket._id != NULL
    status: 404, code: 'BucketNotFoundError', message: 'This bucket does not exist. It may already be deleted.';
  $accessKey := system.randomText(length: 20, alphabet: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567');
  $secretKey := system.randomText(length: 40, alphabet: 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/');
  $credential := INSERT storage.local_bucket_credentials {
      accessKey: $accessKey,
      bucketId: $bucketId,
      expiresAt: $expiresAt::timestamptz,
      isActive: true,
      isRoot: false,
      name: $name::text,
      permissions: coalesce(to_jsonb($permissions(type: text[])), jsonb_build_array()),
      secretKey: $secretKey
    } -> { _id, name, accessKey, isRoot, isActive, expiresAt, creationDate, permissions, bucketId };
  SELECT {
    _id := $credential._id,
    name := $credential.name,
    accessKey := $credential.accessKey,
    isRoot := $credential.isRoot,
    isActive := $credential.isActive,
    expiresAt := $credential.expiresAt,
    creationDate := $credential.creationDate,
    permissions := $credential.permissions,
    bucketId := $credential.bucketId,
    secretKey := $secretKey
  }

$target := SELECT storage.local_bucket_credentials { isRoot } FILTER _id == $id;
  ASSERT not ($target.isRoot ?? false) status: 409, code: 'RootCredentialNotRevocableError', message: 'The root credential cannot be revoked. Rotate it instead.';
  REQUIRED SELECT storage.local_bucket_credentials { _id } FILTER _id == $id;
  UPDATE storage.local_bucket_credentials [_id == $id AND isActive == true] { isActive: false };
  SELECT storage.local_bucket_credentials { _id, isActive } FILTER _id == $id

$accessKey := system.randomText(length: 20, alphabet: 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567');
  $secretKey := system.randomText(length: 40, alphabet: 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/');
  UPDATE storage.local_bucket_credentials [isRoot == true] { accessKey: $accessKey, secretKey: $secretKey };
  $root := SELECT storage.local_bucket_credentials { accessKey } FILTER isRoot == true TAKE 1;
  ASSERT $root.accessKey == $accessKey
    status: 404, code: 'RootCredentialNotFoundError', message: 'The root credential was not rotated. It may not exist, or the caller may not replace its keys.';
  SELECT { accessKey := $accessKey, secretKey := $secretKey }

SELECT storage.local_bucket_credentials {
