  $signed := system.presignObject(bucketId: $bucketId, key: $key(type: string), operation: 'get', transform: $transform(type: object, default: null));
  SELECT { url := $signed.url, expiresAt := $signed.expiresAt, transformed := $signed.transformed }

$bucket := SELECT storage.buckets { _id } FILTER _id::text == $bucketId(type: string) TAKE 1;
