SELECT storage.image_renders {
    _id, variant, state, body, contentType, failure,
    stale := state == 'pending' AND startedAt < now() - make_interval(0, 0, 0, 0, 0, 0, $staleSeconds::numeric)
  }
  FILTER bucketId == $bucketId AND key == $key AND etag == $etag AND variant IN $variants

SUMMARIZE storage.image_renders {
    version := count(*) IF (bucketId == $bucketId AND key == $key AND etag == $etag AND _createdAt > now() - make_interval(0, 0, 0, 0, 0, 0, $versionSeconds::numeric)),
    versionOldest := min(_createdAt) IF (bucketId == $bucketId AND key == $key AND etag == $etag AND _createdAt > now() - make_interval(0, 0, 0, 0, 0, 0, $versionSeconds::numeric)),
    base := count(*) IF (_createdAt > now() - make_interval(0, 0, 0, 0, 0, 0, $baseSeconds::numeric)),
    baseOldest := min(_createdAt) IF (_createdAt > now() - make_interval(0, 0, 0, 0, 0, 0, $baseSeconds::numeric))
  } FILTER variant != 'source'

INSERT storage.image_renders {
    bucketId: $bucketId,
    key: $key,
    etag: $etag,
    variant: $variant,
    format: $format,
    resize: $resize,
    state: 'pending',
    startedAt: now()
  } ON CONFLICT (bucketId, key, etag, variant) DO NOTHING -> { _id }

ASSERT $expiresAt(type: string)::timestamptz == NULL OR $expiresAt::timestamptz > now()
    status: 400, code: 'BadRequestError', message: 'expiresAt must be in the future';
  $bucket := SELECT storage.buckets { _id } FILTER _id::text == $bucketId(type: string) TAKE 1;
  ASSERT $bucket._id != NULL
    status: 404, code: 'BucketNotFoundError', message: 'This bucket does not exist. It may already be deleted.';
  $token := system.newSecret();
  $passwordHash := system.hashPassword(value: $password(type: string));
  $link := INSERT storage.storage_share {
      bucketId: $bucketId,
      expiresAt: $expiresAt::timestamptz,
      maxUses: $maxUses(type: number),
      metadata: jsonb_build_object(
        'keys', coalesce(to_jsonb($keys(type: text[])), jsonb_build_array()),
        'prefixes', coalesce(to_jsonb($prefixes(type: text[])), jsonb_build_array())),
      password: $passwordHash,
      requiresPassword: $passwordHash != NULL,
      revokedAt: NULL,
      tokenHash: system.sha256(value: $token),
      type: 'download',
      usesCount: 0
    } -> { _id };
  SELECT { _id := $link._id, token := $token }

ASSERT coalesce(length($uploadPrefix(type: string)), 0) >= 1
    status: 400, code: 'BadRequestError', message: 'uploadPrefix is required';
  ASSERT $expiresAt(type: string)::timestamptz == NULL OR $expiresAt::timestamptz > now()
    status: 400, code: 'BadRequestError', message: 'expiresAt must be in the future';
  ASSERT $maxFileSize(type: number)::numeric == NULL OR $maxFileSize::numeric >= 1
    status: 400, code: 'BadRequestError', message: 'Maximum file size must be at least 1 byte.';
  $bucket := SELECT storage.buckets { _id } FILTER _id::text == $bucketId(type: string) TAKE 1;
  ASSERT $bucket._id != NULL
    status: 404, code: 'BucketNotFoundError', message: 'This bucket does not exist. It may already be deleted.';
  $token := system.newSecret();
  $passwordHash := system.hashPassword(value: $password(type: string));
  $link := INSERT storage.storage_share {
      bucketId: $bucketId,
      expiresAt: $expiresAt::timestamptz,
      maxUses: $maxUses(type: number),
      metadata: jsonb_strip_nulls(jsonb_build_object(
        'allowedMimeTypes', coalesce(to_jsonb($allowedMimeTypes(type: text[])), jsonb_build_array()),
        'maxFileSize', $maxFileSize(type: number),
        'uploadPrefix', $uploadPrefix(type: text))),
      password: $passwordHash,
      requiresPassword: $passwordHash != NULL,
      revokedAt: NULL,
      tokenHash: system.sha256(value: $token),
      type: 'upload',
      usesCount: 0
    } -> { _id };
  SELECT { _id := $link._id, token := $token }

SELECT storage.storage_share {
      *,
      @unmask password,
      _createdAt,
      status := CASE(revokedAt != NULL, 'revoked',
        CASE(expiresAt != NULL AND expiresAt < now(), 'expired',
          CASE(maxUses != NULL AND usesCount >= maxUses, 'exhausted', 'active')))
  } FILTER tokenHash == $tokenHash AND type == $type TAKE 1

REQUIRED SELECT storage.storage_share { _id } FILTER _id == $id;
  UPDATE storage.storage_share [_id == $id AND revokedAt == NULL] { revokedAt: now() };
  SELECT storage.storage_share { _id, revokedAt } FILTER _id == $id

UPDATE storage.storage_share [_id == $id AND (maxUses == NULL OR usesCount < maxUses)]
    { usesCount: usesCount + 1 }
    -> { _id, usesCount, maxUses }

LOCK 'wyndb-upload-decision', $id(type: uuid, required)::text;
  $request := SELECT storage.upload_requests {
    _id,
    status,
    visible := ($context.designAuthority ?? false) OR can('storage.upload_requests.read'),
    decides := ($context.designAuthority ?? false) OR can('storage.upload_requests.update')
  } FILTER _id == $id;
  ASSERT $request._id != NULL AND $request.visible
    status: 404, code: 'UploadRequestNotFoundError', message: 'This upload request does not exist, or you cannot see it.';
  ASSERT $request.decides
    status: 403, code: 'ForbiddenError', message: 'You may not decide this upload request.';
  ASSERT $request.status == 'pending'
    status: 409, code: 'UploadRequestDecidedError', message: 'This upload request is already decided.';
  ASSERT $decision(type: string, required) IN ['approve', 'refuse']
    status: 400, code: 'BadRequestError', message: 'A decision is approve or refuse.';
  UPDATE storage.upload_requests [_id == $id AND status == 'pending'] {
    status: CASE($decision == 'approve', 'approved', 'refused'),
    decidedBy: $context.userId,
    decidedAt: clock_timestamp(),
    reason: NULLIF($reason(type: string), '')
  };
  $settled := system.settleHeldUpload(requestId: $id::text, decision: $decision);
  ASSERT ($settled.blocked ?? '') != 'inPlace'
    status: 409, code: 'UploadRequestInPlaceError', message: 'This upload already reached its key; approve it to record the decision.';
  ASSERT ($settled.blocked ?? '') != 'breaksLimits'
    status: 409, code: 'UploadBreaksLimitsError', message: 'This upload breaks the limits of the share or file column it came through; refuse it.';
  ASSERT ($settled.blocked ?? '') != 'attachmentRejected'
    status: 409, code: 'UploadAttachmentRejectedError', message: 'The attachment this upload was brought for is already rejected; refuse it.';
  SELECT storage.upload_requests { _id, status, decidedBy := decidedBy._id, decidedAt, reason } FILTER _id == $id

$request := SELECT storage.upload_requests {
    _id,
    status,
    key,
    bucketId := bucket._id,
    visible := ($context.designAuthority ?? false) OR can('storage.upload_requests.read'),
    decides := ($context.designAuthority ?? false) OR can('storage.upload_requests.update')
  } FILTER _id == $id(type: uuid, required);
  ASSERT $request._id != NULL AND $request.visible
    status: 404, code: 'UploadRequestNotFoundError', message: 'This upload request does not exist, or you cannot see it.';
  ASSERT $request.decides
    status: 403, code: 'ForbiddenError', message: 'You may not decide this upload request.';
  ASSERT $request.status == 'pending'
    status: 409, code: 'UploadRequestDecidedError', message: 'This upload request is already decided.';
  $signed := system.presignHeldObject(bucketId: $request.bucketId::text, key: $request.key, requestId: $id::text);
  SELECT { url := $signed.url, expiresAt := $signed.expiresAt }

ASSERT $kind IN ['department', 'product_team', 'office'] code: 'BAD_KIND', message: 'Unknown unit kind', status: 400;
  $root := SELECT auth.teams { _id } FILTER parent IS NULL AND name == CASE($kind == 'department', 'Departments', $kind == 'product_team', 'Product Teams', 'Offices') TAKE 1;
  $t := INSERT EFFECTIVE FROM $effectiveFrom auth.teams { name: $name, parent: $parentTeamId(type: uuid) ?? $root._id } -> { _id };
  $u := INSERT EFFECTIVE FROM $effectiveFrom org.units { team: $t._id, kind: $kind, code: $code, status: 'active', costCenter: $costCenter(type: string), head: $head(type: uuid), country ?= $country, legalEntity ?= $legalEntity } -> { _id };
  SELECT { unitId := $u._id, teamId := $t._id }

$u := SELECT org.units { _id, t := team._id } FILTER _id == $unitId(type: uuid, required);
  ASSERT $u._id != NULL code: 'UNIT_NOT_FOUND', message: 'No unit with that id', status: 404;
  UPDATE EFFECTIVE FROM $effectiveFrom auth.teams [_id == $u.t] { parent: $newParentTeamId(type: uuid, required) } -> { _id }

$u := SELECT org.units { _id } FILTER _id == $unitId(type: uuid, required);
  ASSERT $u._id != NULL code: 'UNIT_NOT_FOUND', message: 'No unit with that id', status: 404;
  UPDATE EFFECTIVE FROM $effectiveFrom org.units [_id == $unitId] { status: 'inactive', status.reason: $reason(type: string) ?? 'Deactivated' } -> { _id }

ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $officeTeamId(type: uuid, required) IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'You can only hire into an office you manage', status: 403;
  ASSERT length(coalesce($jobTitle(type: string), '')) > 0 code: 'JOB_TITLE_REQUIRED', message: 'Job title is required', status: 400;
  ASSERT length(coalesce($employeeNumber(type: string), '')) > 0 code: 'EMPLOYEE_NUMBER_REQUIRED', message: 'Employee number is required', status: 400;
  $head := SELECT org.units { h := head._id } FILTER team == $departmentTeamId(type: uuid, required) TAKE 1;
  $queued := job.sendEmail(
    message: 'account.password_enroll',
    to: $email,
    links: jsonb_build_object('setPasswordUrl', jsonb_build_object('path', '/set-password', 'params', jsonb_build_object('identifier', $email(type: text)),
      'token', jsonb_build_object('purpose', 'password_enroll', 'username', $username(type: text), 'param', 'token')))
  );
  $u := INSERT auth.users { username: $username, name: concat($givenName(type: string, required)::text, ' ', $familyName(type: string, required)::text), givenName: $givenName, familyName: $familyName, nickname: $preferredName(type: string) } -> { _id };
  $em := INSERT auth.emails { user: $u._id, email: $email, primary: true, label: 'work' } -> { user };
  $e := INSERT EFFECTIVE FROM $hireDate(type: date, required) hr.employees {
    person: $u._id, employeeNumber: $employeeNumber, hireDate: $hireDate, originalHireDate: coalesce($originalHireDate(type: date), $hireDate),
    jobTitle: $jobTitle, jobTitle.reason: 'Hire', department: $departmentTeamId, productTeam: $productTeamId(type: uuid), office: $officeTeamId,
    manager: $managerUserId(type: uuid), costCenter: $costCenter(type: string), legalEntity: $legalEntityId(type: uuid),
    status: 'active', status.reason: 'Hire', employmentType: $employmentType, workerType: coalesce($workerType(type: string), 'employee'),
    approver: coalesce($managerUserId, $head.h), currentManager: $managerUserId, currentOffice: $officeTeamId
  } -> { _id };
  INSERT EFFECTIVE FROM $hireDate hr.compensation { employee: $e._id, payRate: $payRate, currency: $currency, payType: $payType, payPeriod: $payPeriod, changeReason: 'Hire' };
  INSERT EFFECTIVE FROM $hireDate auth.team_memberships EACH (SELECT auth.teams { t := _id } FILTER _id IN [$departmentTeamId, $officeTeamId, $productTeamId]) { team: $item.t, user: $u._id };
  SELECT { employeeId := $e._id, userId := $u._id }

$cur := SELECT EFFECTIVE $effectiveFrom(type: date, required) hr.employees { _id, uid := person._id, dep := department._id, off := office._id, pt := productTeam._id, et := employmentType } FILTER _id == $employeeId(type: uuid, required);
  ASSERT $cur._id != NULL code: 'EMPLOYEE_NOT_FOUND', message: 'No employee with that id', status: 404;
  ASSERT length(coalesce($reason(type: string)::text, '')) > 0 code: 'REASON_REQUIRED', message: 'A reason is required for a change', status: 400;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR ($cur.off IN $context.teamIdsLed AND coalesce($officeTeamId(type: uuid)::uuid, $cur.off) == $cur.off) code: 'OUT_OF_SCOPE', message: 'Only an HR admin can move an employee to another office', status: 403;
  // Reads of $cur must happen before the employee row changes: named results are re-read by every later statement.
  $cs := SELECT org.units { c := btrim(country::text, '"') } FILTER team == coalesce($officeTeamId::uuid, $cur.off) TAKE 1;
  INSERT pto.pending_recalcs EACH (SELECT pto.seq { n } FILTER n == 0 AND $effectiveFrom < current_date AND ($employmentType(type: string)::text IS NOT NULL OR $officeTeamId::uuid IS NOT NULL))
    { scope: jsonb_build_object('kind', 'employee', 'employeeId', $employeeId::text, 'country', $cs.c, 'employmentType', coalesce($employmentType::text, $cur.et)), fromDate: $effectiveFrom, reason: 'Back-dated job change: ' || $reason::text, status: 'open', officeTeam: coalesce($officeTeamId::uuid, $cur.off) };
  INSERT EFFECTIVE FROM $effectiveFrom auth.team_memberships EACH (SELECT auth.teams { t := _id } FILTER _id == $departmentTeamId(type: uuid)::uuid AND _id != $cur.dep) { team: $item.t, user: $cur.uid };
  DELETE EFFECTIVE FROM $effectiveFrom auth.team_memberships [user == $cur.uid AND team == $cur.dep AND $departmentTeamId::uuid IS NOT NULL AND $departmentTeamId::uuid != $cur.dep];
  INSERT EFFECTIVE FROM $effectiveFrom auth.team_memberships EACH (SELECT auth.teams { t := _id } FILTER _id == $officeTeamId::uuid AND _id != $cur.off) { team: $item.t, user: $cur.uid };
  DELETE EFFECTIVE FROM $effectiveFrom auth.team_memberships [user == $cur.uid AND team == $cur.off AND $officeTeamId::uuid IS NOT NULL AND $officeTeamId::uuid != $cur.off];
  INSERT EFFECTIVE FROM $effectiveFrom auth.team_memberships EACH (SELECT auth.teams { t := _id } FILTER _id == $productTeamId(type: uuid)::uuid AND (_id != $cur.pt OR $cur.pt IS NULL)) { team: $item.t, user: $cur.uid };
  DELETE EFFECTIVE FROM $effectiveFrom auth.team_memberships [user == $cur.uid AND team == $cur.pt AND $productTeamId::uuid IS NOT NULL AND $productTeamId::uuid != $cur.pt];
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $jobTitle(type: string)::text IS NOT NULL] { jobTitle: coalesce($jobTitle::text, ''), jobTitle.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $departmentTeamId::uuid IS NOT NULL] { department: coalesce($departmentTeamId::uuid, $cur.dep), department.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $productTeamId::uuid IS NOT NULL] { productTeam: $productTeamId::uuid, productTeam.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $officeTeamId::uuid IS NOT NULL] { office: coalesce($officeTeamId::uuid, $cur.off), office.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $managerUserId(type: uuid)::uuid IS NOT NULL] { manager: $managerUserId::uuid, manager.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $costCenter(type: string)::text IS NOT NULL] { costCenter: $costCenter::text, costCenter.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $legalEntityId(type: uuid)::uuid IS NOT NULL] { legalEntity: $legalEntityId::uuid, legalEntity.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $employmentType::text IS NOT NULL] { employmentType: coalesce($employmentType::text, $cur.et), employmentType.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $workerType(type: string)::text IS NOT NULL] { workerType: coalesce($workerType::text, 'employee'), workerType.reason: $reason::text };
  // Mirrors in place (UPDATE HARD): a versioning UPDATE would make $now re-read a closed row and write NULL.
  $now := SELECT hr.employees { p := person._id, m := manager._id, d := department._id, o := office._id } FILTER _id == $employeeId TAKE 1;
  $mst := SELECT hr.employees { s := status } FILTER person == $now.m TAKE 1;
  $head := SELECT org.units { h := head._id } FILTER team == $now.d TAKE 1;
  UPDATE HARD hr.employees [_id == $employeeId] { approver: CASE($now.m IS NOT NULL AND $mst.s == 'active', $now.m, $head.h IS NOT NULL AND $head.h != $now.p, $head.h, NULL), currentManager: $now.m, currentOffice: $now.o };
  SELECT { recalcRequired := $effectiveFrom < current_date AND ($employmentType::text IS NOT NULL OR $officeTeamId::uuid IS NOT NULL) }

$e := SELECT hr.employees { _id, off := office._id } FILTER _id == $employeeId(type: uuid, required);
  ASSERT $e._id != NULL code: 'EMPLOYEE_NOT_FOUND', message: 'No employee with that id', status: 404;
  ASSERT length(coalesce($reason(type: string)::text, '')) > 0 code: 'REASON_REQUIRED', message: 'A reason is required for a correction', status: 400;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR ($e.off IN $context.teamIdsLed AND $officeTeamId(type: uuid)::uuid IS NULL) code: 'OUT_OF_SCOPE', message: 'Only an HR admin can correct the office', status: 403;
  $pJ := SELECT EFFECTIVE ALL hr.employees_jobTitle { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart(type: date, required) TAKE 1;
  $pD := SELECT EFFECTIVE ALL hr.employees_department { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart TAKE 1;
  $pP := SELECT EFFECTIVE ALL hr.employees_productTeam { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart TAKE 1;
  $pO := SELECT EFFECTIVE ALL hr.employees_office { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart TAKE 1;
  $pM := SELECT EFFECTIVE ALL hr.employees_manager { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart TAKE 1;
  $pC := SELECT EFFECTIVE ALL hr.employees_costCenter { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart TAKE 1;
  $pL := SELECT EFFECTIVE ALL hr.employees_legalEntity { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart TAKE 1;
  ASSERT ($jobTitle(type: string)::text IS NULL OR $pJ._id != NULL)
     AND ($departmentTeamId(type: uuid)::uuid IS NULL OR $pD._id != NULL)
     AND ($productTeamId(type: uuid)::uuid IS NULL OR $pP._id != NULL)
     AND ($officeTeamId::uuid IS NULL OR $pO._id != NULL)
     AND ($managerUserId(type: uuid)::uuid IS NULL OR $pM._id != NULL)
     AND ($costCenter(type: string)::text IS NULL OR $pC._id != NULL)
     AND ($legalEntityId(type: uuid)::uuid IS NULL OR $pL._id != NULL)
     code: 'NO_PERIOD_AT_START', message: 'No period starts at that date for a field you are correcting; use Add change for a new event', status: 409;
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $jobTitle::text IS NOT NULL] { jobTitle: UPDATE { value: coalesce($jobTitle::text, ''), reason: $reason::text } };
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $departmentTeamId::uuid IS NOT NULL] { department: UPDATE { value: $departmentTeamId::uuid, reason: $reason::text } };
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $productTeamId::uuid IS NOT NULL] { productTeam: UPDATE { value: $productTeamId::uuid, reason: $reason::text } };
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $officeTeamId::uuid IS NOT NULL] { office: UPDATE { value: $officeTeamId::uuid, reason: $reason::text } };
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $managerUserId::uuid IS NOT NULL] { manager: UPDATE { value: $managerUserId::uuid, reason: $reason::text } };
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $costCenter::text IS NOT NULL] { costCenter: UPDATE { value: $costCenter::text, reason: $reason::text } };
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $legalEntityId::uuid IS NOT NULL] { legalEntity: UPDATE { value: $legalEntityId::uuid, reason: $reason::text } };
  SELECT { recalcRequired := false }

$cur := SELECT EFFECTIVE $effectiveFrom(type: date, required) hr.employees { _id, off := office._id, st := status } FILTER _id == $employeeId(type: uuid, required);
  ASSERT $cur._id != NULL code: 'EMPLOYEE_NOT_FOUND', message: 'No employee with that id', status: 404;
  ASSERT length(coalesce($reason(type: string)::text, '')) > 0 code: 'REASON_REQUIRED', message: 'A reason is required for a status change', status: 400;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $cur.off IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'You can only change employees of an office you manage', status: 403;
  ASSERT ($cur.st == 'active' AND $status(type: string, required)::text IN ['leave', 'terminated']) OR ($cur.st == 'leave' AND $status::text IN ['active', 'terminated']) code: 'ILLEGAL_TRANSITION', message: 'This status change is not allowed (allowed: active↔leave, active/leave→terminated)', status: 409;
  ASSERT $status::text != 'terminated' OR ($terminationReason(type: string)::text IS NOT NULL AND $terminationType(type: string)::text IS NOT NULL) code: 'TERMINATION_REASON_REQUIRED', message: 'Termination requires a reason and a type', status: 400;
  ASSERT $status::text != 'leave' OR $leaveType(type: string)::text IS NOT NULL code: 'LEAVE_TYPE_REQUIRED', message: 'Leave requires a leave type', status: 400;
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId] { status: $status::text, status.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $status::text == 'leave'] { leaveType: $leaveType::text, leaveType.reason: $reason::text };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $status::text == 'active' AND $cur.st == 'leave'] { leaveType: null };
  UPDATE EFFECTIVE FROM $effectiveFrom hr.employees [_id == $employeeId AND $status::text == 'terminated'] { terminationReason: $terminationReason::text, terminationReason.reason: $reason::text, terminationType: $terminationType::text, terminationNote: $terminationNote(type: string)::text };
  UPDATE hr.employees [_id == $employeeId AND $status::text == 'terminated'] { terminationDate: $effectiveFrom };
  SELECT { recalcRequired := false }

$e := SELECT hr.employees { _id, off := office._id } FILTER _id == $employeeId(type: uuid, required);
  ASSERT $e._id != NULL code: 'EMPLOYEE_NOT_FOUND', message: 'No employee with that id', status: 404;
  ASSERT length(coalesce($reason(type: string)::text, '')) > 0 code: 'REASON_REQUIRED', message: 'A reason is required for a correction', status: 400;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $e.off IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'You can only correct employees of an office you manage', status: 403;
  $pS := SELECT EFFECTIVE ALL hr.employees_status { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart(type: date, required) TAKE 1;
  $pE := SELECT EFFECTIVE ALL hr.employees_employmentType { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart TAKE 1;
  $pW := SELECT EFFECTIVE ALL hr.employees_workerType { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart TAKE 1;
  $pR := SELECT EFFECTIVE ALL hr.employees_terminationReason { _id } FILTER owner == $employeeId AND _effectiveFrom == $periodStart TAKE 1;
  ASSERT ($employmentType(type: string)::text IS NULL OR $pE._id != NULL)
     AND ($workerType(type: string)::text IS NULL OR $pW._id != NULL)
     AND ($terminationReason(type: string)::text IS NULL OR $pR._id != NULL)
     AND ($leaveType(type: string)::text IS NULL OR $pS._id != NULL)
     code: 'NO_PERIOD_AT_START', message: 'No period starts at that date for a field you are correcting; use Change status for a new event', status: 409;
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $employmentType::text IS NOT NULL] { employmentType: UPDATE { value: $employmentType::text, reason: $reason::text } };
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $workerType::text IS NOT NULL] { workerType: UPDATE { value: $workerType::text, reason: $reason::text } };
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $terminationReason::text IS NOT NULL] { terminationReason: UPDATE { value: $terminationReason::text, reason: $reason::text } };
  UPDATE EFFECTIVE FROM $periodStart hr.employees [_id == $employeeId AND $leaveType::text IS NOT NULL] { leaveType: UPDATE { value: $leaveType::text, reason: $reason::text } };
  SELECT { recalcRequired := false }

$e := SELECT hr.employees { _id, off := office._id } FILTER _id == $employeeId(type: uuid, required);
  ASSERT $e._id != NULL code: 'EMPLOYEE_NOT_FOUND', message: 'No employee with that id', status: 404;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $e.off IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'You can only change pay for an office you manage', status: 403;
  ASSERT length(coalesce($changeReason(type: string)::text, '')) > 0 code: 'REASON_REQUIRED', message: 'A reason is required', status: 400;
  UPSERT EFFECTIVE FROM $effectiveFrom(type: date, required) hr.compensation [employee == $employeeId] { employee: $employeeId, payRate: $payRate, currency: $currency, payType: $payType, payPeriod: $payPeriod, changeReason: $changeReason::text } -> { _id }

$e := SELECT hr.employees { _id, off := office._id } FILTER _id == $employeeId(type: uuid, required);
  ASSERT $e._id != NULL code: 'EMPLOYEE_NOT_FOUND', message: 'No employee with that id', status: 404;
  $p := SELECT EFFECTIVE ALL hr.compensation { _id } FILTER _id == $periodId(type: uuid, required) AND employee == $employeeId TAKE 1;
  ASSERT $p._id != NULL code: 'PERIOD_NOT_FOUND', message: 'No compensation period with that id for this employee', status: 404;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $e.off IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'You can only correct pay for an office you manage', status: 403;
  ASSERT length(coalesce($changeReason(type: string)::text, '')) > 0 code: 'REASON_REQUIRED', message: 'A reason is required', status: 400;
  UPDATE EFFECTIVE ALL hr.compensation [_id == $periodId] { payRate: $payRate, currency: $currency, payType: $payType, payPeriod: $payPeriod, changeReason: $changeReason::text } -> { _id }

ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role OR 'employee' IN $context.role) code: 'FORBIDDEN', message: 'Only an HR admin can assign roles', status: 403;
  DELETE HARD auth.user_roles [user == $userId(type: uuid, required) AND role.name IN ['hr_admin', 'hr_manager', 'employee']];
  INSERT auth.user_roles EACH (SELECT auth.roles { r := _id } FILTER name IN $roles(type: text[], required)) { user: $userId, role: $item.r }

$me := SELECT hr.employees { _id } FILTER person == self() TAKE 1;
  ASSERT $me._id != NULL code: 'NOT_AN_EMPLOYEE', message: 'You have no employee record', status: 404;
  DELETE hr.emergency_contacts [employee == $me._id];
  INSERT hr.emergency_contacts EACH $contacts { employee: $me._id, name: $item.name, relationship: $item.relationship, phone: $item.phone, isPrimary: coalesce($item.isPrimary::boolean, false) }

$now := SELECT hr.employees { p := person._id, m := manager._id, d := department._id, o := office._id } FILTER _id == $employeeId(type: uuid, required) TAKE 1;
  $mst := SELECT hr.employees { s := status } FILTER person == $now.m TAKE 1;
  $head := SELECT org.units { h := head._id } FILTER team == $now.d TAKE 1;
  UPDATE HARD hr.employees [_id == $employeeId] { approver: CASE($now.m IS NOT NULL AND $mst.s == 'active', $now.m, $head.h IS NOT NULL AND $head.h != $now.p, $head.h, NULL), currentManager: $now.m, currentOffice: $now.o } -> { _id }

$e := SELECT hr.employees { _id, off := currentOffice._id } FILTER person == $userId(type: uuid, required) TAKE 1;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $e.off IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'You can only invite employees of an office you manage', status: 403;
  $address := SELECT auth.emails { _id, email } FILTER user == $userId AND primary == true TAKE 1;
  ASSERT $address._id != NULL code: 'NO_PRIMARY_EMAIL', message: 'The account has no primary email address', status: 404;
  $r := job.sendEmail(
    message: 'account.password_enroll',
    to: $address.email,
    links: jsonb_build_object('setPasswordUrl', jsonb_build_object('path', '/set-password', 'params', jsonb_build_object('identifier', $address.email),
      'token', jsonb_build_object('purpose', 'password_enroll', 'userId', $userId::text, 'emailId', $address._id, 'param', 'token')))
  );
  ASSERT ($r.reason ?? '') != 'rate-limited' code: 'RATE_LIMITED', message: 'Too many messages were queued just now. Try again in a minute.', status: 429;
  ASSERT $r.queued code: 'MAIL_NOT_QUEUED', message: 'This base cannot send email right now, so the set-password link was not sent.', status: 503;
  SELECT { queued := $r.queued }

$e := SELECT hr.employees { _id, off := currentOffice._id } FILTER person == $userId(type: uuid, required) TAKE 1;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $e.off IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'You can only manage accounts of an office you manage', status: 403;
  ASSERT $context.userId IS NULL OR $userId != $context.userId::uuid code: 'SELF', message: 'You cannot change your own account state', status: 400;
  UPDATE auth.users [_id == $userId] { deactivatedAt: CASE($active(type: boolean, required), NULL, coalesce(deactivatedAt, now())) } -> { _id, deactivatedAt }

ASSERT $frequency(type: string, required)::text IN ['monthly', 'semi_monthly', 'biweekly'] code: 'BAD_FREQUENCY', message: 'frequency must be monthly, semi_monthly or biweekly', status: 400;
  INSERT pto.pay_periods EACH (SELECT pto.seq { s := make_date($year(type: integer, required)::int, n, 1) } FILTER n BETWEEN 1 AND 12 AND $frequency::text == 'monthly')
    { country: $country(type: string, required), frequency: 'monthly', periodStart: $item.s, periodEnd: (($item.s + make_interval(0, 1)) - make_interval(0, 0, 0, 1))::date, payDate: (($item.s + make_interval(0, 1)) - make_interval(0, 0, 0, 1))::date }
    ON CONFLICT (country, frequency, periodStart) DO NOTHING;
  INSERT pto.pay_periods EACH (SELECT pto.seq { s := make_date($year::int, (n + 1) / 2, CASE(n % 2 == 1, 1, 16)), half := n % 2 } FILTER n BETWEEN 1 AND 24 AND $frequency::text == 'semi_monthly')
    { country: $country, frequency: 'semi_monthly', periodStart: $item.s, periodEnd: CASE($item.half == 1, ($item.s + make_interval(0, 0, 0, 14))::date, ((date_trunc('month', $item.s) + make_interval(0, 1)) - make_interval(0, 0, 0, 1))::date), payDate: CASE($item.half == 1, ($item.s + make_interval(0, 0, 0, 14))::date, ((date_trunc('month', $item.s) + make_interval(0, 1)) - make_interval(0, 0, 0, 1))::date) }
    ON CONFLICT (country, frequency, periodStart) DO NOTHING;
  INSERT pto.pay_periods EACH (SELECT pto.seq { s := (make_date($year::int, 1, 1) + make_interval(0, 0, 0, ((8 - date_part('isodow', make_date($year::int, 1, 1))::int) % 7) + n * 14))::date } FILTER n BETWEEN 0 AND 26 AND $frequency::text == 'biweekly' AND date_part('year', (make_date($year::int, 1, 1) + make_interval(0, 0, 0, ((8 - date_part('isodow', make_date($year::int, 1, 1))::int) % 7) + n * 14))::date) == $year::int)
    { country: $country, frequency: 'biweekly', periodStart: $item.s, periodEnd: ($item.s + make_interval(0, 0, 0, 13))::date, payDate: ($item.s + make_interval(0, 0, 0, 13))::date }
    ON CONFLICT (country, frequency, periodStart) DO NOTHING;
  SUMMARIZE pto.pay_periods { n := count(*) } FILTER country == $country AND frequency == $frequency::text AND date_part('year', periodStart) == $year::int

INSERT pto.holidays EACH (SELECT pto.holidays { m := date_part('month', date)::int, d := date_part('day', date)::int, nm := name } FILTER country == $country(type: string, required) AND year == $fromYear(type: integer, required)::int AND status == 'active')
    { country: $country, year: $toYear(type: integer, required)::int, date: make_date($toYear::int, $item.m, CASE($item.m == 2 AND $item.d == 29, 28, $item.d)), name: $item.nm, status: 'draft' }
    ON CONFLICT (country, date) DO NOTHING;
  SUMMARIZE pto.holidays { n := count(*) } FILTER country == $country AND year == $toYear::int AND status == 'draft'

$emp := SELECT hr.employees { off := currentOffice._id, et := employmentType } FILTER _id == $employeeId(type: uuid, required) TAKE 1;
  $cs := SELECT org.units { c := btrim(country::text, '"') } FILTER team == $emp.off TAKE 1;
  $set := SELECT org.country_settings { wd := weekendDays } FILTER btrim(country::text, '"') == $cs.c TAKE 1;
  $pol := SELECT pto.policies { hpd := hoursPerDay } FILTER type.code == coalesce($typeCode(type: string)::text, 'VAC') AND country == $cs.c AND employmentType == $emp.et TAKE 1;
  $hol := SUMMARIZE pto.holidays { ds := array_agg(date) } FILTER btrim(country::text, '"') == $cs.c AND status == 'active' AND date BETWEEN $startDate(type: date, required) AND $endDate(type: date, required);
  SELECT pto.seq {
    date := ($startDate + make_interval(0, 0, 0, n))::date,
    hours := coalesce(jsonb_extract_path_text($partial(type: jsonb), (($startDate + make_interval(0, 0, 0, n))::date)::text)::numeric, coalesce($pol.hpd, 8))
  } FILTER n <= ($endDate - $startDate)
    AND NOT (date_part('isodow', ($startDate + make_interval(0, 0, 0, n))::date)::int == ANY(coalesce($set.wd, ARRAY[6, 7])))
    AND NOT (($startDate + make_interval(0, 0, 0, n))::date == ANY(coalesce($hol.ds, ARRAY[]::date[])))
  SORT n

$me := SELECT hr.employees { _id } FILTER person == self() TAKE 1;
  SUMMARIZE pto.ledger {
    accrued := coalesce(sum(hours) IF kind IN ['accrual', 'carryover', 'transfer_in'], 0),
    used := coalesce(0 - (sum(hours) IF kind IN ['usage', 'reversal']), 0),
    adjusted := coalesce(sum(hours) IF kind == 'adjustment', 0),
    expired := coalesce(0 - (sum(hours) IF kind IN ['expiry', 'forfeit', 'payout', 'transfer_out']), 0),
    balance := sum(hours)
  } BY type, type.code, type.name
  FILTER employee == coalesce($employeeId(type: uuid)::uuid, $me._id) AND entryDate <= coalesce($asOf(type: date)::date, current_date)

$me := SELECT hr.employees { _id, uid := person._id, off := currentOffice._id, et := employmentType, st := status } FILTER person == self() TAKE 1;
  ASSERT $me._id != NULL code: 'NOT_AN_EMPLOYEE', message: 'You have no employee record', status: 404;
  ASSERT $me.st != 'terminated' code: 'TERMINATED', message: 'Terminated employees cannot request time off', status: 403;
  ASSERT $endDate(type: date, required) >= $startDate(type: date, required) code: 'BAD_RANGE', message: 'The end date is before the start date', status: 400;
  $cs := SELECT org.units { c := btrim(country::text, '"') } FILTER team == $me.off TAKE 1;
  $pol := SELECT pto.policies { mode := accrualMode, rate := accrualHoursPerPeriod, freq := payFrequency, grant := annualGrantHours, neg := negativeBalanceLimitHours, minp := minPartialHours, tcode := type.code } FILTER type == $typeId(type: uuid, required) AND country == $cs.c AND employmentType == $me.et TAKE 1;
  ASSERT $pol.mode != NULL code: 'NO_POLICY', message: 'No time off policy covers you for this type', status: 400;
  $wh := SUMMARIZE pto.workingHours(employeeId: $me._id, startDate: $startDate, endDate: $endDate, partial: $partial(type: jsonb), typeCode: $pol.tcode) { total := coalesce(sum(hours), 0), minh := min(hours), days := jsonb_agg(jsonb_build_object('date', to_char(date, 'YYYY-MM-DD'), 'hours', hours)) };
  ASSERT $wh.total > 0 code: 'NO_WORKING_DAYS', message: 'The selected range has no working days', status: 400;
  ASSERT $wh.minh >= $pol.minp code: 'PARTIAL_TOO_SHORT', message: 'A partial day must be at least the policy minimum (2 hours)', status: 400;
  $ov := SELECT pto.requests { _id } FILTER employee == $me._id AND status IN ['pending', 'approved'] AND startDate <= $endDate AND endDate >= $startDate TAKE 1;
  ASSERT $ov._id == NULL code: 'OVERLAP', message: 'This overlaps another pending or approved request', status: 409;
  $bal := SUMMARIZE pto.ledger { b := coalesce(sum(hours), 0) } FILTER employee == $me._id AND type == $typeId;
  $pend := SUMMARIZE pto.requests { p := coalesce(sum(totalHours), 0) } FILTER employee == $me._id AND type == $typeId AND status == 'pending';
  $fut := SUMMARIZE pto.pay_periods { n := count(*) } FILTER btrim(country::text, '"') == $cs.c AND frequency == $pol.freq AND periodEnd > current_date AND periodEnd <= $startDate;
  ASSERT $pol.mode == 'unlimited' OR ($bal.b - $pend.p + CASE($pol.mode == 'per_period', coalesce($pol.rate, 0) * $fut.n, $pol.mode == 'annual_grant' AND date_part('year', $startDate) > date_part('year', current_date), coalesce($pol.grant, 0), 0) - $wh.total) >= (0 - $pol.neg) code: 'INSUFFICIENT_BALANCE', message: 'Not enough projected balance for this request', status: 409;
  INSERT pto.requests { employee: $me._id, type: $typeId, startDate: $startDate, endDate: $endDate, days: $wh.days, totalHours: $wh.total, note: $note(type: string), requester: $me.uid, officeTeam: $me.off, status: 'pending' } -> { _id, totalHours, status }

$r := SELECT pto.requests { _id, st := status, sd := startDate, req := requester._id, off := officeTeam._id } FILTER _id == $requestId(type: uuid, required) TAKE 1;
  ASSERT $r._id != NULL code: 'REQUEST_NOT_FOUND', message: 'No request with that id', status: 404;
  ASSERT $r.st IN ['pending', 'approved'] code: 'NOT_CANCELABLE', message: 'Only pending or approved requests can be canceled', status: 409;
  ASSERT 'hr_admin' IN $context.role OR ('hr_manager' IN $context.role AND $r.off IN $context.teamIdsLed) OR ($context.userId IS NOT NULL AND $r.req == $context.userId::uuid AND ($r.st == 'pending' OR $r.sd > current_date)) OR ($context.userId IS NULL) code: 'FORBIDDEN', message: 'You can cancel an approved request only before it starts; ask HR after that', status: 403;
  INSERT pto.ledger EACH (SELECT pto.ledger { e := employee._id, t := type._id, h := hours, i := _id } FILTER request == $requestId AND kind == 'usage')
    { employee: $item.e, type: $item.t, kind: 'reversal', hours: 0 - $item.h, entryDate: current_date, reason: coalesce($reason(type: string)::text, 'Request canceled'), request: $requestId, idemKey: 'rev:' || $item.i::text }
    ON CONFLICT (idemKey) DO NOTHING;
  UPDATE pto.requests [_id == $requestId] { status: 'canceled', decisionNote: $reason::text, decidedBy: $context.userId::uuid, decidedAt: now() } -> { _id, status }

$e := SELECT hr.employees { _id, off := currentOffice._id } FILTER _id == $employeeId(type: uuid, required) TAKE 1;
  ASSERT $e._id != NULL code: 'EMPLOYEE_NOT_FOUND', message: 'No employee with that id', status: 404;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $e.off IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'You can only adjust balances for an office you manage', status: 403;
  ASSERT length(coalesce($reason(type: string)::text, '')) > 0 code: 'REASON_REQUIRED', message: 'An adjustment needs a reason', status: 400;
  INSERT pto.ledger { employee: $employeeId, type: $typeId(type: uuid, required), kind: 'adjustment', hours: $hours(type: number, required), entryDate: coalesce($entryDate(type: date)::date, current_date), reason: $reason::text } -> { _id, hours }

$me := SELECT hr.employees { _id } FILTER person == self() TAKE 1;
  SELECT pto.requests { requestId := _id, employeeId := employee._id, name := employee.person.name, typeId := type._id, typeName := type.name, startDate, endDate, days, totalHours, note, status, decidedBy, decidedAt, decisionNote, overriddenByHr, _createdAt }
  FILTER employee == coalesce($employeeId(type: uuid)::uuid, $me._id)
  SORT -startDate

ASSERT $effectiveFrom(type: date, required) IS NOT NULL code: 'DATE_REQUIRED', message: 'An effective date is required', status: 400;
  UPSERT EFFECTIVE FROM $effectiveFrom pto.policies [type == $typeId(type: uuid, required) AND country == $country(type: string, required)::text AND employmentType == $employmentType(type: string, required)::text] {
    name: $name(type: string, required), type: $typeId, country: $country::text, employmentType: $employmentType::text, accrualMode: $accrualMode(type: string, required)::text,
    accrualHoursPerPeriod: $accrualHoursPerPeriod(type: number), payFrequency: $payFrequency(type: string)::text, annualGrantHours: $annualGrantHours(type: number),
    prorateFirstPeriod: coalesce($prorateFirstPeriod(type: boolean)::boolean, true), accrualCapPerYear: $accrualCapPerYear(type: number), maxCarryover: $maxCarryover(type: number),
    carryoverExpiresAfterMonths: $carryoverExpiresAfterMonths(type: integer), negativeBalanceLimitHours: coalesce($negativeBalanceLimitHours(type: number)::numeric, 0),
    minPartialHours: coalesce($minPartialHours(type: number)::numeric, 2), hoursPerDay: coalesce($hoursPerDay(type: number)::numeric, 8),
    accrueDuringLeave: coalesce($accrueDuringLeave(type: boolean)::boolean, false), onTermination: coalesce($onTermination(type: string)::text, 'forfeit')
  };
  INSERT pto.pending_recalcs EACH (SELECT pto.seq { n } FILTER n == 0 AND $effectiveFrom < current_date)
    { scope: jsonb_build_object('kind', 'policy', 'typeId', $typeId::text, 'country', $country::text, 'employmentType', $employmentType::text), fromDate: $effectiveFrom, reason: 'Policy change: ' || $name::text, status: 'open' };
  SELECT { recalcRequired := $effectiveFrom < current_date }

$pol := SELECT EFFECTIVE $asOf(type: date, required) pto.policies { rate := accrualHoursPerPeriod, cap := accrualCapPerYear, prorate := prorateFirstPeriod, lv := accrueDuringLeave, freq := payFrequency } FILTER type == $typeId(type: uuid, required) AND country == $country(type: string, required)::text AND employmentType == $employmentType(type: string, required)::text AND accrualMode == 'per_period' TAKE 1;
  $pp := SELECT pto.pay_periods { _id, s := periodStart, e := periodEnd, len := (periodEnd - periodStart + 1) } FILTER btrim(country::text, '"') == $country::text AND frequency == $pol.freq AND periodEnd == $asOf TAKE 1;
  $offs := SUMMARIZE org.units { ts := array_agg(team._id) } FILTER kind == 'office' AND btrim(country::text, '"') == $country::text;
  INSERT pto.ledger EACH (SELECT EFFECTIVE $asOf hr.employees { emp := _id, hd := hireDate, ytd := ledgerEntries[sum(hours) FILTER type == $typeId AND entryDate >= date_trunc('year', $asOf)::date AND (kind == 'accrual' OR (kind == 'reversal' AND idemKey LIKE 'recalc-rev:%'))] }
      FILTER $pp._id IS NOT NULL AND employmentType == $employmentType::text AND (status == 'active' OR (status == 'leave' AND $pol.lv)) AND hireDate <= $asOf AND currentOffice == ANY(coalesce($offs.ts, ARRAY[]::uuid[]))
        AND ($employeeId(type: uuid)::uuid IS NULL OR _id == $employeeId::uuid))
    { employee: $item.emp, type: $typeId, kind: 'accrual',
      hours: round(greatest(0, least($pol.rate * CASE($pol.prorate AND $item.hd > $pp.s, ($pp.e - $item.hd + 1)::numeric / $pp.len, 1), coalesce($pol.cap - coalesce($item.ytd, 0), 1000000))), 4),
      entryDate: $asOf, payPeriod: $pp._id, recalcBatch: $batch(type: string)::text,
      idemKey: 'acc:' || $item.emp::text || ':' || $typeId::text || ':' || $pp._id::text || coalesce(':' || $batch::text, '') }
    ON CONFLICT (idemKey) DO NOTHING;
  SUMMARIZE pto.ledger { n := count(*), h := sum(hours) } FILTER kind == 'accrual' AND type == $typeId AND entryDate == $asOf

$pol := SELECT EFFECTIVE $asOf(type: date, required) pto.policies { g := annualGrantHours, lv := accrueDuringLeave } FILTER type == $typeId(type: uuid, required) AND country == $country(type: string, required)::text AND employmentType == $employmentType(type: string, required)::text AND accrualMode == 'annual_grant' TAKE 1;
  $cs := SELECT org.country_settings { m := leaveYearStartMonth, d := leaveYearStartDay } FILTER btrim(country::text, '"') == $country::text TAKE 1;
  $y := SELECT org.country_settings { ys := CASE($asOf >= make_date(date_part('year', $asOf)::int, leaveYearStartMonth, leaveYearStartDay), make_date(date_part('year', $asOf)::int, leaveYearStartMonth, leaveYearStartDay), make_date(date_part('year', $asOf)::int - 1, leaveYearStartMonth, leaveYearStartDay)) } FILTER btrim(country::text, '"') == $country::text TAKE 1;
  $offs := SUMMARIZE org.units { ts := array_agg(team._id) } FILTER kind == 'office' AND btrim(country::text, '"') == $country::text;
  INSERT pto.ledger EACH (SELECT EFFECTIVE $asOf hr.employees { emp := _id, hd := hireDate }
      FILTER $pol.g IS NOT NULL AND employmentType == $employmentType::text AND (status == 'active' OR (status == 'leave' AND $pol.lv)) AND currentOffice == ANY(coalesce($offs.ts, ARRAY[]::uuid[]))
        AND (($asOf == $y.ys AND hireDate <= $y.ys) OR (hireDate == $asOf AND hireDate > $y.ys)))
    { employee: $item.emp, type: $typeId, kind: 'accrual',
      hours: round(CASE($item.hd <= $y.ys, $pol.g, $pol.g * (12 - (date_part('year', age($item.hd, $y.ys)) * 12 + date_part('month', age($item.hd, $y.ys))))::numeric / 12), 4),
      entryDate: $asOf, idemKey: 'grant:' || $item.emp::text || ':' || $typeId::text || ':' || $y.ys::text }
    ON CONFLICT (idemKey) DO NOTHING;
  SUMMARIZE pto.ledger { n := count(*), h := sum(hours) } FILTER kind == 'accrual' AND type == $typeId AND entryDate == $asOf AND idemKey LIKE 'grant:%'

$pol := SELECT EFFECTIVE $asOf(type: date, required) pto.policies { mc := coalesce(maxCarryover, 0) } FILTER type == $typeId(type: uuid, required) AND country == $country(type: string, required)::text AND employmentType == $employmentType(type: string, required)::text AND accrualMode != 'unlimited' TAKE 1;
  $offs := SUMMARIZE org.units { ts := array_agg(team._id) } FILTER kind == 'office' AND btrim(country::text, '"') == $country::text;
  INSERT pto.ledger EACH (SELECT EFFECTIVE $asOf hr.employees { emp := _id, bal := ledgerEntries[sum(hours) FILTER type == $typeId AND entryDate <= $asOf] }
      FILTER $pol.mc IS NOT NULL AND employmentType == $employmentType::text AND status != 'terminated' AND currentOffice == ANY(coalesce($offs.ts, ARRAY[]::uuid[])) AND ledgerEntries[sum(hours) FILTER type == $typeId AND entryDate <= $asOf] > 0)
    { employee: $item.emp, type: $typeId, kind: 'expiry', hours: 0 - $item.bal, entryDate: $asOf, reason: 'Leave year closed', idemKey: 'ye-exp:' || $item.emp::text || ':' || $typeId::text || ':' || $asOf::text }
    ON CONFLICT (idemKey) DO NOTHING;
  INSERT pto.ledger EACH (SELECT EFFECTIVE $asOf hr.employees { emp := _id, carry := least($pol.mc, coalesce(ledgerEntries[sum(hours) FILTER type == $typeId AND entryDate < $asOf], 0)) }
      FILTER $pol.mc > 0 AND employmentType == $employmentType::text AND status != 'terminated' AND currentOffice == ANY(coalesce($offs.ts, ARRAY[]::uuid[])) AND ledgerEntries[count(*) FILTER idemKey == 'ye-exp:' || $row._id::text || ':' || $typeId::text || ':' || $asOf::text] > 0)
    { employee: $item.emp, type: $typeId, kind: 'carryover', hours: $item.carry, entryDate: ($asOf + make_interval(0, 0, 0, 1))::date, reason: 'Carried over', idemKey: 'ye-carry:' || $item.emp::text || ':' || $typeId::text || ':' || $asOf::text }
    ON CONFLICT (idemKey) DO NOTHING;
  SUMMARIZE pto.ledger { n := count(*), h := sum(hours) } BY kind FILTER type == $typeId AND (idemKey LIKE 'ye-exp:%' OR idemKey LIKE 'ye-carry:%') AND (entryDate == $asOf OR entryDate == ($asOf + make_interval(0, 0, 0, 1))::date)

$e := SELECT EFFECTIVE $effectiveFrom(type: date, required) hr.employees { _id, et := employmentType, off := currentOffice._id } FILTER _id == $employeeId(type: uuid, required) TAKE 1;
  $cs := SELECT org.units { c := btrim(country::text, '"') } FILTER team == $e.off TAKE 1;
  INSERT pto.ledger EACH (SELECT pto.ledger { e := employee._id, t := type._id, h := hours, i := _id, r := request._id } FILTER employee == $employeeId AND kind == 'usage' AND request.status == 'approved' AND request.startDate >= $effectiveFrom)
    { employee: $item.e, type: $item.t, kind: 'reversal', hours: 0 - $item.h, entryDate: $effectiveFrom, reason: 'Employment ended', request: $item.r, idemKey: 'rev:' || $item.i::text }
    ON CONFLICT (idemKey) DO NOTHING;
  UPDATE pto.requests [employee == $employeeId AND status IN ['pending', 'approved'] AND startDate >= $effectiveFrom] { status: 'canceled', decisionNote: 'Employment ended', decidedAt: now() };
  INSERT pto.ledger EACH (SELECT pto.types { t := _id, b := ledgerEntries[sum(hours) FILTER employee == $employeeId AND entryDate <= $effectiveFrom] }
      FILTER ledgerEntries[sum(hours) FILTER employee == $employeeId AND entryDate <= $effectiveFrom] > 0 AND policies[count(*) FILTER country == $cs.c AND employmentType == $e.et AND accrualMode != 'unlimited' AND onTermination == 'payout'] > 0)
    { employee: $employeeId, type: $item.t, kind: 'payout', hours: 0 - $item.b, entryDate: $effectiveFrom, reason: 'Employment ended: paid out', idemKey: 'term:' || $employeeId::text || ':' || $item.t::text }
    ON CONFLICT (idemKey) DO NOTHING;
  INSERT pto.ledger EACH (SELECT pto.types { t := _id, b := ledgerEntries[sum(hours) FILTER employee == $employeeId AND entryDate <= $effectiveFrom] }
      FILTER ledgerEntries[sum(hours) FILTER employee == $employeeId AND entryDate <= $effectiveFrom] > 0 AND policies[count(*) FILTER country == $cs.c AND employmentType == $e.et AND accrualMode != 'unlimited' AND onTermination == 'forfeit'] > 0)
    { employee: $employeeId, type: $item.t, kind: 'forfeit', hours: 0 - $item.b, entryDate: $effectiveFrom, reason: 'Employment ended: forfeited', idemKey: 'term:' || $employeeId::text || ':' || $item.t::text }
    ON CONFLICT (idemKey) DO NOTHING;
  SUMMARIZE pto.ledger { n := count(*), h := sum(hours) } BY kind FILTER employee == $employeeId AND idemKey LIKE 'term:%'

ASSERT 'hr_admin' IN $context.role OR 'hr_manager' IN $context.role code: 'FORBIDDEN', message: 'Only HR can preview recalculations', status: 403;
  $p := SELECT pto.pending_recalcs { _id, scope, fromDate } FILTER _id == $pendingRecalcId(type: uuid, required) TAKE 1;
  $offs := SUMMARIZE org.units { ts := array_agg(team._id) } FILTER kind == 'office' AND btrim(country::text, '"') == jsonb_extract_path_text($p.scope, 'country');
  SELECT hr.employees {
    employeeId := _id, name := person.name, employmentType,
    currentAccrued := ledgerEntries[coalesce(sum(hours), 0) FILTER entryDate >= $p.fromDate AND (kind == 'accrual' OR (kind == 'reversal' AND idemKey LIKE 'recalc-rev:%'))],
    periodsInRange := @cell (SUMMARIZE pto.pay_periods { n := count(*) } FILTER periodEnd >= $p.fromDate AND periodEnd <= current_date AND frequency == 'monthly'),
    fromDate := $p.fromDate
  } FILTER status != 'terminated' AND anonymizedAt IS NULL
    AND ('hr_admin' IN $context.role OR currentOffice IN $context.teamIdsLed)
    AND ((jsonb_extract_path_text($p.scope, 'kind') == 'employee' AND _id::text == jsonb_extract_path_text($p.scope, 'employeeId'))
      OR (jsonb_extract_path_text($p.scope, 'kind') == 'policy' AND employmentType == jsonb_extract_path_text($p.scope, 'employmentType')
          AND currentOffice == ANY(coalesce($offs.ts, ARRAY[]::uuid[]))))

$p := SELECT pto.pending_recalcs { _id, scope, fromDate, st := status, off := officeTeam._id } FILTER _id == $pendingRecalcId(type: uuid, required) TAKE 1;
  ASSERT $p._id != NULL code: 'NOT_FOUND', message: 'No pending recalculation with that id', status: 404;
  ASSERT $p.st == 'open' code: 'NOT_OPEN', message: 'This recalculation is not open', status: 409;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $p.off IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'You can only apply recalculations for an office you manage', status: 403;
  $offs := SUMMARIZE org.units { ts := array_agg(team._id) } FILTER kind == 'office' AND btrim(country::text, '"') == jsonb_extract_path_text($p.scope, 'country');
  INSERT pto.ledger EACH (SELECT pto.ledger { i := _id, e := employee._id, t := type._id, h := hours } FILTER kind == 'accrual' AND entryDate >= $p.fromDate AND idemKey NOT LIKE 'grant:%'
      AND ((jsonb_extract_path_text($p.scope, 'kind') == 'employee' AND employee._id::text == jsonb_extract_path_text($p.scope, 'employeeId'))
        OR (jsonb_extract_path_text($p.scope, 'kind') == 'policy' AND type._id::text == jsonb_extract_path_text($p.scope, 'typeId')
            AND employee.currentOffice == ANY(coalesce($offs.ts, ARRAY[]::uuid[]))
            AND employee.employmentType == jsonb_extract_path_text($p.scope, 'employmentType'))))
    { employee: $item.e, type: $item.t, kind: 'reversal', hours: 0 - $item.h, entryDate: current_date, reason: 'Recalculation ' || $pendingRecalcId::text, recalcBatch: $pendingRecalcId::text, idemKey: 'recalc-rev:' || $item.i::text }
    ON CONFLICT (idemKey) DO NOTHING;
  UPDATE pto.pending_recalcs [_id == $pendingRecalcId AND status == 'open'] { status: 'applying' } -> { _id, status }

$p := SELECT pto.pending_recalcs { _id, off := officeTeam._id } FILTER _id == $pendingRecalcId(type: uuid, required) AND status == 'open' TAKE 1;
  ASSERT $p._id != NULL code: 'NOT_OPEN', message: 'No open recalculation with that id', status: 409;
  ASSERT 'hr_admin' IN $context.role OR NOT ('hr_manager' IN $context.role) OR $p.off IN $context.teamIdsLed code: 'OUT_OF_SCOPE', message: 'Out of scope', status: 403;
  UPDATE pto.pending_recalcs [_id == $pendingRecalcId] { status: 'dismissed', reason: reason || ' — dismissed: ' || coalesce($reason(type: string)::text, '') } -> { _id, status }

$emp := SELECT hr.employees { off := currentOffice._id, et := employmentType } FILTER person == $context.userId::uuid TAKE 1;
  $cs := SELECT org.units { c := btrim(country::text, '"') } FILTER team == $emp.off TAKE 1;
  $set := SELECT org.country_settings { wd := weekendDays } FILTER btrim(country::text, '"') == $cs.c TAKE 1;
  $pol := SELECT pto.policies { hpd := hoursPerDay } FILTER type.code == coalesce($typeCode(type: string)::text, 'VAC') AND country == $cs.c AND employmentType == $emp.et TAKE 1;
  $hol := SUMMARIZE pto.holidays { ds := array_agg(date) } FILTER btrim(country::text, '"') == $cs.c AND status == 'active' AND date BETWEEN $startDate(type: date, required) AND $endDate(type: date, required);
  SELECT pto.seq {
    date := ($startDate + make_interval(0, 0, 0, n))::date,
    hours := coalesce(jsonb_extract_path_text($partial(type: jsonb), (($startDate + make_interval(0, 0, 0, n))::date)::text)::numeric, coalesce($pol.hpd, 8))
  } FILTER $emp.off IS NOT NULL AND n <= ($endDate - $startDate) AND n <= 120
    AND NOT (date_part('isodow', ($startDate + make_interval(0, 0, 0, n))::date)::int == ANY(coalesce($set.wd, ARRAY[6, 7])))
    AND NOT (($startDate + make_interval(0, 0, 0, n))::date == ANY(coalesce($hol.ds, ARRAY[]::date[])))
  SORT n

SELECT pto.holidays { holidayId := _id, country := btrim(country::text, '"'), date, name, status }
  FILTER btrim(country::text, '"') == $country(type: string, required)::text AND date_part('year', date)::int == $year(type: int, required)
  SORT +date

SELECT pto.pay_periods { payPeriodId := _id, country := btrim(country::text, '"'), frequency, periodStart, periodEnd }
  FILTER btrim(country::text, '"') == $country(type: string, required)::text AND date_part('year', periodEnd)::int == $year(type: int, required)
  SORT +periodStart

$om := SUMMARIZE org.units { m := jsonb_object_agg(team._id::text, btrim(country::text, '"')) } FILTER kind == 'office';
  SELECT hr.employees {
    employeeId := _id, name := person.name, jobTitle, department, office, officeTeamId := office._id,
    country := jsonb_extract_path_text($om.m, currentOffice._id::text),
    leave := (SELECT timeOffRequests { startDate, endDate, days, category := type.category }
              FILTER status == 'approved' AND startDate <= $to(type: date, required) AND endDate >= $from(type: date, required))
  } FILTER status != 'terminated' AND anonymizedAt IS NULL
    AND ($employeeId(type: uuid)::uuid IS NULL OR _id == $employeeId::uuid)
    AND ($officeTeamId(type: uuid)::uuid IS NULL OR currentOffice == $officeTeamId::uuid)
    AND ($departmentTeamId(type: uuid)::uuid IS NULL OR department == $departmentTeamId::uuid)
  SORT name

SELECT pto.holidays { country := btrim(country::text, '"'), date, name }
  FILTER status == 'active' AND date >= $from(type: date, required) AND date <= $to(type: date, required)
  SORT +date

$om := SUMMARIZE org.units { m := jsonb_object_agg(team._id::text, btrim(country::text, '"')) } FILTER kind == 'office';
  $pol := SUMMARIZE gdpr.retention_policies { m := jsonb_object_agg(country, retainYearsAfterTermination) };
  SELECT hr.employees { employeeId := _id, employeeNumber, name := person.name, terminationDate, country := jsonb_extract_path_text($om.m, currentOffice._id::text), retainYears := jsonb_extract_path_text($pol.m, jsonb_extract_path_text($om.m, currentOffice._id::text))::int }
  FILTER status == 'terminated' AND anonymizedAt IS NULL AND terminationDate IS NOT NULL
    AND jsonb_extract_path_text($pol.m, jsonb_extract_path_text($om.m, currentOffice._id::text)) IS NOT NULL
    AND terminationDate + make_interval(jsonb_extract_path_text($pol.m, jsonb_extract_path_text($om.m, currentOffice._id::text))::int) < coalesce($asOf(type: date)::date, current_date)

$e := SELECT hr.employees { _id, uid := person._id, num := employeeNumber, st := status, an := anonymizedAt } FILTER _id == $employeeId(type: uuid, required) TAKE 1;
  ASSERT $e._id != NULL code: 'NOT_FOUND', message: 'No such employee', status: 404;
  ASSERT $e.st == 'terminated' code: 'NOT_TERMINATED', message: 'Only terminated employees can be anonymized', status: 409;
  ASSERT $e.an IS NULL code: 'ALREADY_ANONYMIZED', message: 'This employee is already anonymized', status: 409;
  DELETE auth.addresses [user == $e.uid];
  DELETE auth.phone_numbers [user == $e.uid];
  DELETE auth.emails [user == $e.uid AND primary == false];
  DELETE hr.emergency_contacts [employee == $e._id];
  DELETE EFFECTIVE ALL hr.compensation [employee == $e._id];
  UPDATE auth.users [_id == $e.uid] { name: 'Former employee ' || coalesce($e.num, ''), givenName: NULL, familyName: NULL, middleName: NULL, nickname: NULL, pronouns: NULL, deactivatedAt: coalesce(deactivatedAt, now()) };
  UPDATE HARD hr.employees [_id == $e._id] { anonymizedAt: now() } -> { _id, anonymizedAt }
